const respuesta = $input.first().json;
const textoJSON = respuesta.content.parts[0].text;
let datosExtraidos = JSON.parse(textoJSON);

// Si Gemini devolvió un array en vez de un objeto, tomamos el primer elemento
if (Array.isArray(datosExtraidos)) {
  datosExtraidos = datosExtraidos[0];
}

// Validar fecha_emision
const fechaValida = /^\d{4}-\d{2}-\d{2}$/.test(datosExtraidos.fecha_emision)
  && datosExtraidos.fecha_emision !== "0000-00-00";
if (!fechaValida) {
  datosExtraidos.fecha_emision = null;
}

datosExtraidos.items = datosExtraidos.items || [];

return [{ json: datosExtraidos }];

const doc = $('Parse Document').item.json;
const consulta = $input.item.json;

// --- Paso 1: campos críticos faltantes → error ---
const camposCriticos = ['numero_documento', 'proveedor_ruc', 'total', 'fecha_emision'];
const faltantes = camposCriticos.filter(campo =>
  doc[campo] === null || doc[campo] === undefined || doc[campo] === ''
);

if (faltantes.length > 0) {
  return {
    ...doc,
    hash_duplicado: null,
    estado_validacion: 'error',
    motivo_revision: `Campos críticos faltantes: ${faltantes.join(', ')}`,
    mensaje_discord: `❌ **Error de extracción**\nDocumento: ${doc.numero_documento || 'sin número'}\nMotivo: Campos críticos faltantes: ${faltantes.join(', ')}`
  };
}

const crypto = require('crypto');
const hash = crypto.createHash('md5')
  .update(`${doc.numero_documento}-${doc.proveedor_ruc}`)
  .digest('hex');

// --- Paso 2: duplicado → no se inserta, se corta aquí ---
if (consulta.es_duplicado > 0) {
  return {
    ...doc,
    hash_duplicado: hash,
    estado_validacion: 'duplicado',
    motivo_revision: 'Documento duplicado (mismo número + RUC ya existe)',
    mensaje_discord: `🔁 **Documento duplicado**\nDocumento: ${doc.numero_documento} (${doc.proveedor_ruc})\nYa existe en la base de datos, no se insertó de nuevo.`
  };
}

// --- Paso 3: anomalía de monto → sí se inserta, marcado para revisión ---
let estado_validacion = 'ok';
let motivos = [];

if (consulta.cantidad_historica >= 3) {
  const promedio = parseFloat(consulta.promedio_historico);
  const desviacion = Math.abs(doc.total - promedio) / promedio;
  if (desviacion > 0.5) {
    estado_validacion = 'revision';
    motivos.push(`Monto atípico: ${doc.total} vs promedio histórico ${promedio.toFixed(2)}`);
  }
}

const mensaje_discord = estado_validacion === 'revision'
  ? `⚠️ **Requiere revisión**\nDocumento: ${doc.numero_documento} (${doc.proveedor_ruc})\nTotal: ${doc.total} ${doc.moneda}\nMotivo: ${motivos.join('; ')}`
  : `✅ Documento procesado: ${doc.numero_documento} — ${doc.total} ${doc.moneda}`;

return {
  ...doc,
  hash_duplicado: hash,
  estado_validacion,
  motivo_revision: motivos.join('; ') || null,
  mensaje_discord
};
